<?php require 'includes/auth.php';require_role('buyer');$pid=(int)($_GET['product_id']??0);$pdo=db();$eligible=$pdo->prepare("SELECT p.name FROM products p WHERE p.id=? AND EXISTS(SELECT 1 FROM order_items oi JOIN seller_orders so ON so.id=oi.seller_order_id JOIN orders o ON o.id=so.order_id WHERE oi.product_id=p.id AND o.buyer_id=? AND so.status='Delivered')");$eligible->execute([$pid,user()['id']]);$product=$eligible->fetch();if(!$product){flash('error','You can review products after a delivered purchase.');redirect('orders.php');}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$rating=(int)post('rating');if($rating<1||$rating>5)flash('error','Choose a rating from 1 to 5.');else{$pdo->prepare('INSERT INTO reviews(buyer_id,product_id,rating,comment) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE rating=VALUES(rating),comment=VALUES(comment),created_at=NOW()')->execute([user()['id'],$pid,$rating,post('comment')]);flash('success','Thank you for your review!');redirect('product.php?id='.$pid);}}$s=$pdo->prepare('SELECT * FROM reviews WHERE buyer_id=? AND product_id=?');$s->execute([user()['id'],$pid]);$r=$s->fetch();$pageTitle='Review '.$product['name'];require 'includes/header.php';?><div class="page-title"><p class="eyebrow">PURCHASE REVIEW</p><h1>Rate <?=e($product['name'])?></h1></div><form method="post" class="card-form narrow"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Rating<select name="rating" required><option value="">Choose a rating</option><?php for($i=5;$i>=1;$i--):?><option value="<?=$i?>" <?=($r['rating']??'')==$i?'selected':''?>><?=$i?> star<?=$i>1?'s':''?></option><?php endfor;?></select></label><label>Review<textarea name="comment" maxlength="1000" placeholder="How was the freshness and quality?"><?=e($r['comment']??'')?></textarea></label><button>Save review</button></form><?php require 'includes/footer.php'; ?>
